import (
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
)

func goldTok(cfg string) *SuffixTokenizer {
	switch cfg {
	case "DropShortTokens":
		return &SuffixTokenizer{DropShortTokens: true}
	case "FilterStopwords":
		return &SuffixTokenizer{FilterStopwords: true}
	case "both":
		return &SuffixTokenizer{DropShortTokens: true, FilterStopwords: true}
	default:
		return &SuffixTokenizer{}
	}
}

type goldCase struct {
	config string
	in     string
	want   []string
}

func TestSuffixGolden_Index(t *testing.T) {
	for _, c := range goldIndexCases {
		assert.Equal(t, c.want, goldTok(c.config).TokenizeForIndex(c.in),
			"index config=%s in=%q", c.config, c.in)
	}
}

func TestSuffixGolden_Search(t *testing.T) {
	for _, c := range goldSearchCases {
		got, wild := goldTok(c.config).TokenizeForSearch(c.in, false)
		assert.Equal(t, c.want, got, "search config=%s in=%q", c.config, c.in)
		assert.Nil(t, wild)
	}
}

func TestSuffixGolden_ExactMatching(t *testing.T) {
	for _, c := range goldExactCases {
		st := goldTok(c.config)
		a, _ := st.TokenizeForSearch(c.in, false)
		b, _ := st.TokenizeForSearch(c.in, true)
		assert.Equal(t, a, b, "exactMatching must not change keywords config=%s in=%q", c.config, c.in)
	}
}

func TestSuffixGolden_Symmetry(t *testing.T) {
	for _, c := range goldSymmetryCases {
		st := goldTok(c.config)
		gotIdx := st.TokenizeForIndex(c.in)
		gotSrch, wild := st.TokenizeForSearch(c.in, false)
		assert.Equal(t, c.idx, gotIdx, "symmetry index config=%s in=%q", c.config, c.in)
		assert.Equal(t, c.srch, gotSrch, "symmetry search config=%s in=%q", c.config, c.in)
		assert.Nil(t, wild)
		for _, q := range gotSrch {
			matched := false
			for _, k := range gotIdx {
				if strings.HasPrefix(k, q) {
					matched = true
					break
				}
			}
			assert.True(t, matched, "search keyword %q must prefix some index key (config=%s in=%q)", q, c.config, c.in)
		}
	}
}

